checkBlockScopedCollisions(
  local: Binding,
  kind: BindingKind,
  name: string,
  id: any,
) {
  // ignore parameters
  if (kind === "param") return;

  // Ignore existing binding if it's the name of the current function or
  // class expression
  if (local.kind === "local") return;

  const duplicate =
    // don't allow duplicate bindings to exist alongside
    kind === "let" ||
    local.kind === "let" ||
    local.kind === "const" ||
    local.kind === "module" ||
    // don't allow a local of param with a kind of let
    (local.kind === "param" && kind === "const");

  if (duplicate) {
    throw this.hub.buildError(
      id,
      `Duplicate declaration "${name}"`,
      TypeError,
    );
  }
}

rename(
  oldName: string,
  newName?: string,
  // prettier-ignore
  /* Babel 7 - block?: t.Pattern | t.Scopable */
) {
  const binding = this.getBinding(oldName);
  if (binding) {
    newName ||= this.generateUidIdentifier(oldName).name;
    const renamer = new Renamer(binding, oldName, newName);
    if (process.env.BABEL_8_BREAKING) {
      binding.rename(renamer, binding.scope, binding.path);
    } else {
      // @ts-ignore(Babel 7 vs Babel 8) TODO: Delete this
      binding.rename(renamer, binding.scope, binding.path, arguments[2]);
    }
  }
}

